import { Room } from "livekit-client";


export class Core {
  constructor() {
    this.room = null;
    this.ws = "";
    this.connectionState = "idle";

    this.mediaOptions = {};
    this.screenOptions = {};

  
    this.events = null;
    this.media = null;
    this.screen = null;
  }

  async init(wsUrl) {
    if (!wsUrl) {
      throw new Error("WebSocket URL is required.");
    }

    this.ws = wsUrl;
    return this;
  }

  
  async join(options = {}) {
  const { token, adaptiveStream = true, dynacast = true, autoSubscribe = true } = options;

  if (!token) {
    throw new Error("Token is required to join room.");
  }

  if (!this.ws) {
    throw new Error("SDK not initialized. Call init(wsUrl) first.");
  }

  if (this.room) {
    await this.leave();
  }

  this.room = new Room({
    adaptiveStream,
    dynacast,
    autoSubscribe,
    publishDefaults: {
      videoCodec:
        options.media?.video?.codec || "vp8"
    }
  });

  this._bindCoreRoomEvents();

  this.connectionState = "connecting";

  await this.room.connect(this.ws, token);

  this.connectionState = "connected";

  return this.room;
}


_bindCoreRoomEvents() {

  if (!this.room) return;

  const room = this.room;

  const originalEmit = room.emit.bind(room);

  room.emit = (event, ...params) => {

    this.events?.emit(event, ...params);

    this.events?.emit(`room:${event}`, ...params);

    return originalEmit(event, ...params);
  };

}


async sendData(data, reliable = true) {

  if (!this.room) {
    throw new Error("Room not connected");
  }

  const encoder = new TextEncoder();

  await this.room.localParticipant.publishData(
    encoder.encode(JSON.stringify(data)),
    { reliable }
  );

}
  
  async leave() {
    if (!this.room) return;

    await this.media?.unpublishTracks();
    await this.screen?.stop();

    this.events?.clear();

    this.room.disconnect();
    this.room = null;

    this.connectionState = "idle";
  }

  
  isConnected() {
    return this.connectionState === "connected";
  }

  getConnectionState() {
    return this.connectionState;
  }
  getRemoteParticipants() {
  return this.room ? Array.from(this.room.remoteParticipants.values()) : [];
}
}