import { EVENTS } from "../rtm";

export class Moderation {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;
    }

    muteUser(roomId, targetUserId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!targetUserId) {
            throw new Error("targetUserId required");
        }

        const payload = {
            room_id: roomId,
            target_user_id: targetUserId
        };

        this.rtm.send(
            EVENTS.USER_MUTE,
            payload
        );

        return payload;
    }

    kickUser(roomId, targetUserId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!targetUserId) {
            throw new Error("targetUserId required");
        }

        const payload = {
            room_id: roomId,
            target_user_id: targetUserId
        };

        this.rtm.send(
            EVENTS.USER_KICK,
            payload
        );

        return payload;
    }
}