import { createLocalTracks, Room } from "livekit-client";
import { MEDIA_PROFILES, VIDEO_CODECS } from "./config/mediaProfiles";

export class Media {
  constructor(core) {
    this.core = core;

    this.localTracks = [];
    this.isPublishing = false;

    this.currentMicId = null;
    this.currentCameraId = null;

    this.currentFacingMode = "user";
  }

  _ensureConnected() {
    if (!this.core.room) {
      throw new Error("Room is not connected. Call join() first.");
    }
  }


  async publishCustomTracks(customOptions = null) {

    this._ensureConnected();

    if (this.localTracks.length > 0 || this.isPublishing) {
      return this.localTracks;
    }

    this.isPublishing = true;

    try {

      const options =
        customOptions ??
        this.core.mediaOptions ??
        {};

      const quality = options.video?.quality ?? "HD";  

      const profile = MEDIA_PROFILES[quality];

      if (!profile) {
        throw new Error("Invalid video quality");
      }

      options.__profile = profile;

      const trackOptions = {
        audio: options.audio ?? true,
        video: options.video ?? true,
      };

      

      if (
        trackOptions.audio &&
        typeof trackOptions.audio !== "object"
      ) {
        trackOptions.audio = {};
      }

      if (options.audioDeviceId) {

        trackOptions.audio.deviceId =
          options.audioDeviceId;

        this.currentMicId =
          options.audioDeviceId;
      }

      

      if (
        trackOptions.video &&
        typeof trackOptions.video !== "object"
      ) {

        trackOptions.video = {};
      }

      if (options.videoDeviceId) {

        trackOptions.video.deviceId =
          options.videoDeviceId;

        this.currentCameraId =
          options.videoDeviceId;
      }

      if (options.facingMode) {

        trackOptions.video.facingMode =
          options.facingMode;

        this.currentFacingMode =
          options.facingMode;
      }

      

      if (
        trackOptions.video &&
        typeof trackOptions.video === "object"
      ) {

        const profile = options.__profile || {};

        trackOptions.video.width =
          options?.video?.width ?? profile.width;

        trackOptions.video.height =
          options?.video?.height ?? profile.height;

        trackOptions.video.frameRate =
          options?.video?.frameRate ?? profile.frameRate;
      }

      const tracks =
        await createLocalTracks(
          trackOptions
        );

      const codec =
        options.video?.codec
          ? VIDEO_CODECS[
          String(options.video.codec).toLowerCase()
          ]
          : profile.defaultCodec;

      for (const track of tracks) {

        await this.core.room
          .localParticipant
          .publishTrack(track, {

            simulcast:
              options.simulcast ?? true,

            videoCodec:
              codec ?? "vp8"
          });
      }

      this.localTracks = tracks;

      tracks.forEach(track => {

        const settings =
          track.mediaStreamTrack
            ?.getSettings?.();

        if (
          track.kind === "video"
        ) {

          if (settings?.deviceId) {
            this.currentCameraId =
              settings.deviceId;
          }

          if (settings?.facingMode) {
            this.currentFacingMode =
              settings.facingMode;
          }
        }

        if (
          track.kind === "audio" &&
          settings?.deviceId
        ) {

          this.currentMicId =
            settings.deviceId;
        }
      });

      this.core.events?.emit(
        "media:published",
        tracks
      );

      return tracks;

    } catch (error) {

      console.error(
        "Failed to publish tracks:",
        error
      );

      throw error;

    } finally {

      this.isPublishing = false;
    }
  }



  async unpublishTracks() {

    if (!this.core.room) {
      this.localTracks = [];
      return;
    }

    for (const track of this.localTracks) {

      try {

        await this.core.room.localParticipant.unpublishTrack(track);
        track.stop();

      } catch (e) {

        console.warn("Track already unpublished or failed to stop", e);

      }

    }

    this.localTracks = [];

    this.core.events?.emit("media:unpublished");

  }



  async enableMic() {
    this._ensureConnected();
    await this.core.room.localParticipant.setMicrophoneEnabled(true);
  }

  async disableMic() {
    this._ensureConnected();
    await this.core.room.localParticipant.setMicrophoneEnabled(false);
  }

  async toggleMic() {
    this._ensureConnected();

    const enabled = this.core.room.localParticipant.isMicrophoneEnabled;

    await this.core.room.localParticipant.setMicrophoneEnabled(!enabled);

    return !enabled;
  }

  isMicEnabled() {
    return this.core.room?.localParticipant?.isMicrophoneEnabled ?? false;
  }



  async enableCamera() {
    this._ensureConnected();
    await this.core.room.localParticipant.setCameraEnabled(true);
  }

  async disableCamera() {
    this._ensureConnected();
    await this.core.room.localParticipant.setCameraEnabled(false);
  }

  async toggleCamera() {
    this._ensureConnected();

    const enabled = this.core.room.localParticipant.isCameraEnabled;

    await this.core.room.localParticipant.setCameraEnabled(!enabled);

    return !enabled;
  }

  isCameraEnabled() {
    return this.core.room?.localParticipant?.isCameraEnabled ?? false;
  }



  async getDevices() {

    return await Room.getLocalDevices();

  }

  async getCameras() {

    const devices = await this.getDevices();

    return devices.filter(d => d.kind === "videoinput");

  }

  async getMicrophones() {

    const devices = await this.getDevices();

    return devices.filter(d => d.kind === "audioinput");

  }


  async switchCamera(deviceId, options = {}) {

    this._ensureConnected();

    const videoTrack =
      this.getLocalVideoTrack();

    if (!videoTrack) {
      throw new Error("No active video track");
    }

    const settings =
      videoTrack.mediaStreamTrack?.getSettings?.() || {};


    const profile =
      options.quality
        ? MEDIA_PROFILES[options.quality]
        : MEDIA_PROFILES.HD;

    
    this.currentCameraId = deviceId;
    const track = await this.republishVideo({
      deviceId,
      quality: options.quality,
      codec: options.codec,
      width: options.width,
      height: options.height,
      frameRate: options.frameRate
    });

    

    this.core.events?.emit(
      "media:camera-switched",
      {
        deviceId,
        width:
          options.width ??
          profile?.width,
        height:
          options.height ??
          profile?.height,
        frameRate:
          options.frameRate ??
          profile?.frameRate,
        codec:
          options.codec ??
          profile?.defaultCodec
      
      }
    );

    return track;
  }
  

  async switchFacingMode(
    mode = "user",
    options = {}
  ) {

    this._ensureConnected();

    const videoTrack =
      this.getLocalVideoTrack();

    if (!videoTrack) {
      throw new Error("No active video track");
    }

    const settings =
      videoTrack.mediaStreamTrack?.getSettings?.() || {};

    const profile =
      options.quality
        ? MEDIA_PROFILES[options.quality]
        : MEDIA_PROFILES.HD;


    this.currentFacingMode = mode;
    const track = await this.republishVideo({
      facingMode: mode,
      quality: options.quality,
      codec: options.codec,
      width: options.width,
      height: options.height,
      frameRate: options.frameRate
    });

    
    this.core.events?.emit(
      "media:facing-mode-changed",
      {
        mode,
        width:
          options.width ??
          profile?.width,
        height:
          options.height ??
          profile?.height,
        frameRate:
          options.frameRate ??
          profile?.frameRate,
        codec:
          options.codec ??
          profile?.defaultCodec
      }
    );

    return track;
  }
  

  async toggleCameraFacing(options = {}) {

    const isMobile =
      /Android|iPhone|iPad|iPod/i.test(
        navigator.userAgent
      );

    if (isMobile) {

      const next =
        this.currentFacingMode === "environment"
          ? "user"
          : "environment";

      await this.switchFacingMode(
        next,
        options
      );

      return next;
    }

    const cameras =
      await this.getCameras();

    if (cameras.length < 2) {
      throw new Error(
        "No secondary camera found"
      );
    }

    const next =
      cameras.find(
        c =>
          c.deviceId !==
          this.currentCameraId
      ) || cameras[0];

    await this.switchCamera(
      next.deviceId,
      options
    );

    return next.deviceId;
  }




  async switchMicrophone(deviceId) {

    this._ensureConnected();

    if (!deviceId) {
      throw new Error("Microphone deviceId required");
    }

    await this.core.room.switchActiveDevice("audioinput", deviceId);

    this.currentMicId = deviceId;
    this.core.events?.emit("media:mic-switched", deviceId);
    return deviceId;
  }


  async recreateMicrophone(options = {}) {

    this._ensureConnected();

    const participant =
      this.core.room.localParticipant;

    let oldTrack = null;

    try {

      oldTrack =
        this.getLocalAudioTrack();

      const wasEnabled =
        participant.isMicrophoneEnabled;

      

      if (oldTrack) {

        await participant.unpublishTrack(
          oldTrack
        );

        oldTrack.stop();

        this.localTracks =
          this.localTracks.filter(
            t => t !== oldTrack
          );
      }

      

      const tracks =
        await createLocalTracks({

          audio: {

            deviceId:
              options.deviceId ??
              this.currentMicId,

            echoCancellation:
              options.echoCancellation ?? true,

            noiseSuppression:
              options.noiseSuppression ?? true,

            autoGainControl:
              options.autoGainControl ?? true,

            
            krisp:
              options.krisp,

            voiceGate:
              options.voiceGate

          },

          video: false

        });

      const newMic =
        tracks.find(
          t => t.kind === "audio"
        );

      if (!newMic) {

        throw new Error(
          "Failed to create microphone track"
        );
      }

      await participant.publishTrack(
        newMic
      );

      this.localTracks.push(
        newMic
      );

      

      const settings =
        newMic.mediaStreamTrack
          ?.getSettings?.();

      if (settings?.deviceId) {

        this.currentMicId =
          settings.deviceId;
      }

      

      if (!wasEnabled) {

        await participant.setMicrophoneEnabled(
          false
        );
      }

      this.core.events?.emit(
        "media:mic-recreated",
        {
          track: newMic,
          options
        }
      );

      return newMic;

    } catch (error) {

      console.error(
        "Failed to recreate microphone:",
        error
      );

      throw error;
    }
  }


  async setNoiseCancellation(enabled = true) {

    return this.recreateMicrophone({

      echoCancellation:
        enabled,

      noiseSuppression:
        enabled,

      autoGainControl:
        enabled,

      krisp:
        enabled,

      voiceGate:
        enabled
    });
  }



  getCurrentCamera() {
    return this.currentCameraId;
  }

  getCurrentMicrophone() {
    return this.currentMicId;
  }


  getLocalVideoTrack() {
    return this.localTracks.find(
      t => t.kind === "video"
    );
  }

  getLocalAudioTrack() {
    return this.localTracks.find(
      t => t.kind === "audio"
    );
  }

  getCurrentFacingMode() {
    return this.currentFacingMode;
  }



async republishVideo(options = {}) {

  this._ensureConnected();

  const participant =
    this.core.room.localParticipant;

  const oldTrack =
    this.getLocalVideoTrack();

  if (!oldTrack) {
    throw new Error("No active video track");
  }

  const settings =
    oldTrack.mediaStreamTrack?.getSettings?.() || {};

  const profile =
    options.quality
      ? MEDIA_PROFILES[options.quality]
      : MEDIA_PROFILES.HD;

  const codec =
    options.codec
      ? VIDEO_CODECS[
      String(options.codec).toLowerCase()
      ]
      : profile.defaultCodec;

  const publication =
    participant.getTrackPublication(
      oldTrack.sid
    );


  await participant.unpublishTrack(oldTrack);

  oldTrack.stop();

  this.localTracks =
    this.localTracks.filter(
      t => t !== oldTrack
    );

  const tracks =
    await createLocalTracks({
      video: {
        deviceId:
          options.deviceId ??
          this.currentCameraId,

        facingMode:
          options.facingMode ??
          this.currentFacingMode,

        width:
          options.width ??
          profile.width,

        height:
          options.height ??
          profile.height,

        frameRate:
          options.frameRate ??
          profile.frameRate
      }
    });

  const newTrack =
    tracks.find(
      t => t.kind === "video"
    );

  await participant.publishTrack(
    newTrack,
    {
      simulcast:
        publication?.simulcasted ?? true,
      videoCodec:
        codec
    }
  );

  this.localTracks.push(
    newTrack
  );

  this.core.events?.emit(
    "media:video-republished",
    newTrack
  );
  
  return newTrack;
}
}





