export class Calls {
  constructor(core) {
    this.core = core;
    this.currentCallId = null;
    this.callState = "idle";
  }

  async startCall(options = {}) {
    const { token, callId = null, media = {}, autoPublish = true } = options;

    if (!token) {
      throw new Error("Token is required to start a call.");
    }

    if (this.callState === "active") {
      throw new Error("Call already active.");
    }

    this.callState = "connecting";
    this.currentCallId = callId;

  
    await this.core.join({
      token,
      media,
      autoPublish
    });

    this.callState = "active";

    this.core.events?.emit("call:started", {
      callId: this.currentCallId
    });

    return true;
  }

  async endCall() {
    if (this.callState !== "active") return;

    await this.core.leave();

    this.callState = "ended";

    this.core.events?.emit("call:ended", {
      callId: this.currentCallId
    });

    this.currentCallId = null;
  }

  
  isInCall() {
    return this.callState === "active";
  }

  getCallState() {
    return this.callState;
  }

  getCallId() {
    return this.currentCallId;
  }

  reset() {
    this.currentCallId = null;
    this.callState = "idle";
  }
}