const EVENTS = Object.freeze({

    ROOM_JOIN: "room.join",
    ROOM_LEAVE: "room.leave",

    CHAT_MESSAGE: "chat.message",
    CHAT_DELETE: "chat.message.delete",

    TYPING_START: "typing.start",
    TYPING_STOP: "typing.stop",

    REACTION_ADD: "reaction.add",

    CHAT_ATTACHMENT: "chat.attachment",

    RAISE_HAND: "raise.hand",
    POLL_VOTE: "poll.vote",

    USER_MUTE: "user.mute",
    USER_KICK: "user.kick",

    CALL_INVITE: "call.invite",
    CALL_ACCEPT: "call.accept",
    CALL_REJECT: "call.reject",

    SCREENSHARE_START: "screenshare.start",
    SCREENSHARE_STOP: "screenshare.stop",

    SIGNAL_OFFER: "signal.offer",
    SIGNAL_ANSWER: "signal.answer",
    SIGNAL_ICE: "signal.ice",

    PRESENCE_UPDATE: "presence.update",
    ROOM_STATE_SYNC: "room.state.sync",

    USER_JOINED: "user.joined",
    USER_LEFT: "user.left",

});

export class RTM {

    constructor() {

        this.socket = null;

        this.connected = false;

        this.token = null;

        this.roomId = null;

        this.handlers = new Map();

        this.EVENTS = EVENTS;
    }

    async connect({ token, roomId }) {

        if (!token) {
            throw new Error("RTM token required");
        }

        if (!roomId) {
            throw new Error("roomId required");
        }

        this.token = token;
        this.roomId = roomId;

        return new Promise((resolve, reject) => {

            this.socket = new WebSocket(
                `wss://rtms.videohub.dev/ws?token=${token}`
            );

            this.socket.onopen = () => {

                this.connected = true;

                this.send(
                    EVENTS.ROOM_JOIN,
                    {
                        room_id: roomId
                    }
                );

                resolve();
            };

            this.socket.onerror = err => {

                reject(err);
            };

            this.socket.onclose = () => {

                this.connected = false;
            };

            this.socket.onmessage = event => {

                try {

                    const data =
                        JSON.parse(event.data);

                    this.handleMessage(data);

                } catch (err) {

                    console.error(
                        "RTM parse error",
                        err
                    );
                }
            };
        });
    }

    disconnect() {

        if (this.socket) {

            this.socket.close();

            this.socket = null;
        }

        this.connected = false;
    }

    send(event, payload = {}) {

        if (!this.connected) {

            throw new Error(
                "RTM not connected"
            );
        }

        this.socket.send(
            JSON.stringify({
                event,
                payload
            })
        );
    }

    on(event, callback) {

        if (!this.handlers.has(event)) {

            this.handlers.set(
                event,
                []
            );
        }

        this.handlers
            .get(event)
            .push(callback);
    }

    off(event, callback) {

        if (!this.handlers.has(event)) {
            return;
        }

        const filtered =
            this.handlers
                .get(event)
                .filter(fn => fn !== callback);

        this.handlers.set(
            event,
            filtered
        );
    }

    emit(event, payload) {

        const listeners =
            this.handlers.get(event);

        if (!listeners) {
            return;
        }

        listeners.forEach(fn => {

            try {

                fn(payload);

            } catch (err) {

                console.error(err);
            }
        });
    }

    handleMessage(data) {

        if (!data?.event) {
            return;
        }

        this.emit(
            data.event,
            data.payload || {}
        );

        this.emit(
            "*",
            data
        );
    }
}

export { EVENTS };