import { createLocalScreenTracks } from "livekit-client";
import { MEDIA_PROFILES, VIDEO_CODECS } from "./config/mediaProfiles";

export class Screen {
  constructor(core) {
    this.core = core;
    this.tracks = [];
    this.isSharing = false;
  }

  _ensureConnected() {
    if (!this.core.room) {
      throw new Error("Room is not connected. Call join() first.");
    }
  }

  async start(customOptions = null) {
    this._ensureConnected();

    if (this.isSharing) {
      return this.tracks;
    }

    const options =
      customOptions ??
      this.core.screenOptions ??
      {};

    const trackOptions = {
      audio:
        options.audio !== undefined
          ? options.audio
          : false,

      video:
        options.video !== undefined
          ? options.video
          : true,
    };

    const publishOptions = {
      simulcast:
        options.simulcast !== undefined
          ? options.simulcast
          : false,

      source: "screen_share",
    };

    this.tracks = await createLocalScreenTracks(trackOptions);

    for (const track of this.tracks) {


      track.on("ended", () => {
        this.stop();
      });

      await this.core.room.localParticipant.publishTrack(
        track,
        publishOptions
      );
    }

    this.isSharing = true;

    return this.tracks;
  }


  async stop() {
    this._ensureConnected();

    if (!this.isSharing) return;

    for (const track of this.tracks) {
      await this.core.room.localParticipant.unpublishTrack(track);
      track.stop();
    }

    this.tracks = [];
    this.isSharing = false;
  }

 
  isActive() {
    return this.isSharing;
  }
}