import { Core } from "./core";
import { Calls } from "./calls";
import { Media } from "./media";
import { Screen } from "./screen";
import { Events } from "./events";
import { RTM } from "./rtm";
import { Chat } from "./rtm/chat";
import { Presence } from "./rtm/presence";
import { Attachment } from "./rtm/attachment";
import { Interaction } from "./rtm/interaction";
import { Moderation } from "./rtm/moderation";
import { ScreenShare } from "./rtm/screenshare";
import { Call } from "./rtm/call";
import { MEDIA_PROFILES, VIDEO_CODECS } from "./config/mediaProfiles";


class VideoHub {
  constructor(config = {}) {
    this.core = new Core();

    this.events = new Events(this.core);
    this.media = new Media(this.core);
    this.screen = new Screen(this.core);
    this.calls = new Calls(this.core);

    this.core.events = this.events;
    this.core.media = this.media;
    this.core.screen = this.screen;

    this.rtm = new RTM();

    this.chat = new Chat(this.rtm);
    this.presence = new Presence(this.rtm);
    this.attachment = new Attachment(this.rtm);
    this.interaction = new Interaction(this.rtm);
    this.moderation = new Moderation(this.rtm);
    this.screenshare = new ScreenShare(this.rtm);
    this.call = new Call(this.rtm);
    
    if (config.ws) {
      this.init(config.ws);
    }
  }

  
  async init(ws) {
    await this.core.init(ws);
    return this;
  }

  
  async join(options = {}) {

    const media = structuredClone(options.media || {});
    let profile = null;

    if (media.video?.quality) {

      profile = MEDIA_PROFILES[media.video.quality];

      if (!profile) {
        throw new Error("Invalid video quality: use SD, HD, FHD, QHD, UHD");
      }

      
    } else {
      profile = MEDIA_PROFILES.HD;
    }


    const codec =
      media.video?.codec
        ? VIDEO_CODECS[
        String(media.video.codec).toLowerCase()
        ]
        : profile.defaultCodec;


    const finalMedia = {

      audio: media.audio ?? true,

      video: {

        width:
          media.video?.width ??
          profile.width,

        height:
          media.video?.height ??
          profile.height,

        frameRate:
          media.video?.frameRate ??
          profile.frameRate,

        codec
      }
    };

    const autoPublish = options.autoPublish ?? true;

    const room = await this.core.join({
      ...options,
      autoPublish
    });

    if (autoPublish) {
      await this.media?.publishCustomTracks(finalMedia);
    }
    return room;
  }
  
  
  async publish(options = {}) {

    const media = structuredClone(options);

    let profile = MEDIA_PROFILES[
      media.video?.quality || "HD"
    ];

    return this.media.publishCustomTracks({
      audio: media.audio ?? true,
      video: {
        width: profile.width,
        height: profile.height,
        frameRate:
          media.video?.frameRate ??
          profile.frameRate,
        codec:
          media.video?.codec ??
          profile.defaultCodec
      }
    });
  }


  async leave() {

    try {

      if (this.rtm?.connected) {

        try {

          this.presence.leaveRoom(
            this.rtm.roomId
          );

        } catch (_) { }

        this.rtm.disconnect();
      }

    } catch (_) { }

    return this.core.leave();
  }

  
  isConnected() {
    return this.core.isConnected();
  }

  getConnectionState() {
    return this.core.getConnectionState();
  }

  
  async destroy() {
    await this.leave();

    this.events?.clear();
    this.calls?.reset();

    this.core = null;
    this.calls = null;
    this.media = null;
    this.screen = null;
    this.events = null;
    
    this.chat = null;
    this.presence = null;
    this.attachment = null;
    this.interaction = null;
    this.moderation = null;
    this.screenshare = null;
    this.call = null;

    this.rtm = null;
  }
}

export default VideoHub;