import { EVENTS } from "../rtm";

export class Attachment {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;
    }

    send(roomId, attachments = []) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!Array.isArray(attachments)) {
            throw new Error("attachments must be an array");
        }

        if (attachments.length === 0) {
            throw new Error("attachments required");
        }

        const normalized = attachments.map(file => {

            if (!file.file_id) {
                throw new Error("file_id required");
            }

            return {
                file_id: file.file_id,
                name: file.name || "",
                size: file.size || 0,
                mime_type: file.mime_type || "",
                url: file.url || ""
            };
        });

        const payload = {
            room_id: roomId,
            attachments: normalized
        };

        this.rtm.send(
            EVENTS.CHAT_ATTACHMENT,
            payload
        );

        return payload;
    }

    sendSingle(roomId, attachment) {

        return this.send(
            roomId,
            [attachment]
        );
    }
}