import { EVENTS } from "../rtm";

export class Interaction {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;
    }

    raiseHand(roomId, raised = true) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        const payload = {
            room_id: roomId,
            raised: Boolean(raised)
        };

        this.rtm.send(
            EVENTS.RAISE_HAND,
            payload
        );

        return payload;
    }

    lowerHand(roomId) {

        return this.raiseHand(
            roomId,
            false
        );
    }

    vote(roomId, pollId, optionId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!pollId) {
            throw new Error("pollId required");
        }

        if (!optionId) {
            throw new Error("optionId required");
        }

        const payload = {
            room_id: roomId,
            poll_id: pollId,
            option_id: optionId
        };

        this.rtm.send(
            EVENTS.POLL_VOTE,
            payload
        );

        return payload;
    }
}