import { EVENTS } from "../rtm";

export class Presence {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;

        this.currentRoomId = null;

        this.onlineUsers = new Map();

        this.handlers = {
            joined: [],
            left: [],
            presence: [],
            roomState: []
        };
    }

    joinRoom(roomId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        this.currentRoomId = roomId;

        this.rtm.send(
            EVENTS.ROOM_JOIN,
            {
                room_id: roomId
            }
        );
    }

    leaveRoom(roomId = this.currentRoomId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        this.rtm.send(
            EVENTS.ROOM_LEAVE,
            {
                room_id: roomId
            }
        );

        this.currentRoomId = null;

        this.onlineUsers.clear();
    }

    handleMessage(event, payload) {

        switch (event) {

            case EVENTS.USER_JOINED:

                this.onlineUsers.set(
                    payload.user_id,
                    true
                );

                this.handlers.joined.forEach(
                    cb => cb(payload)
                );

                break;

            case EVENTS.USER_LEFT:

                this.onlineUsers.delete(
                    payload.user_id
                );

                this.handlers.left.forEach(
                    cb => cb(payload)
                );

                break;

            case EVENTS.PRESENCE_UPDATE:

                if (payload.online) {

                    this.onlineUsers.set(
                        payload.user_id,
                        true
                    );

                } else {

                    this.onlineUsers.delete(
                        payload.user_id
                    );
                }

                this.handlers.presence.forEach(
                    cb => cb(payload)
                );

                break;

            case EVENTS.ROOM_STATE_SYNC:

                this.onlineUsers.clear();

                if (
                    Array.isArray(
                        payload.participants
                    )
                ) {

                    payload.participants.forEach(
                        userId => {

                            this.onlineUsers.set(
                                userId,
                                true
                            );

                        }
                    );
                }

                this.handlers.roomState.forEach(
                    cb => cb(payload)
                );

                break;
        }
    }

    getOnlineUsers() {

        return Array.from(
            this.onlineUsers.keys()
        );
    }

    getOnlineCount() {

        return this.onlineUsers.size;
    }

    onUserJoined(callback) {

        this.handlers.joined.push(
            callback
        );
    }

    onUserLeft(callback) {

        this.handlers.left.push(
            callback
        );
    }

    onPresenceUpdate(callback) {

        this.handlers.presence.push(
            callback
        );
    }

    onRoomStateSync(callback) {

        this.handlers.roomState.push(
            callback
        );
    }
}