import { EVENTS } from "../rtm";

export class Call {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;
    }

    invite(
        targetUserId,
        roomId,
        callerName = "HOST"
    ) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!targetUserId) {
            throw new Error("targetUserId required");
        }

        const payload = {
            target_user_id: targetUserId,
            room_id: roomId,
            caller_name: callerName,
            rtc_room: roomId
        };

        this.rtm.send(
            EVENTS.CALL_INVITE,
            payload
        );

        return payload;
    }

    accept(
        roomId,
        callerId,
        userId
    ) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!callerId) {
            throw new Error("callerId required");
        }

        const payload = {
            target_user_id: callerId,
            room_id: roomId,
            user_id: userId
        };

        this.rtm.send(
            EVENTS.CALL_ACCEPT,
            payload
        );

        return payload;
    }

    reject(
        roomId,
        callerId,
        userId
    ) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!callerId) {
            throw new Error("callerId required");
        }

        const payload = {
            target_user_id: callerId,
            room_id: roomId,
            user_id: userId
        };

        this.rtm.send(
            EVENTS.CALL_REJECT,
            payload
        );

        return payload;
    }
}