import { EVENTS } from "../rtm";

export class ScreenShare {

    constructor(rtm) {

        if (!rtm) {
            throw new Error("RTM instance required");
        }

        this.rtm = rtm;
    }

    start(roomId, streamId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!streamId) {
            throw new Error("streamId required");
        }

        const payload = {
            room_id: roomId,
            stream_id: streamId
        };

        this.rtm.send(
            EVENTS.SCREENSHARE_START,
            payload
        );

        return payload;
    }

    stop(roomId, streamId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!streamId) {
            throw new Error("streamId required");
        }

        const payload = {
            room_id: roomId,
            stream_id: streamId
        };

        this.rtm.send(
            EVENTS.SCREENSHARE_STOP,
            payload
        );

        return payload;
    }
}