import { EVENTS } from "../rtm";

export class Chat {

    constructor(rtm) {
        this.rtm = rtm;
    }

    send(
        roomId,
        message,
        messageId = crypto.randomUUID()
    ) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!message?.trim()) {
            throw new Error("Message required");
        }

        this.rtm.send(
            EVENTS.CHAT_MESSAGE,
            {
                room_id: roomId,
                message,
                message_id: messageId
            }
        );

        return messageId;
    }




    sendRichMessage(
        roomId,
        payload,
        messageId = crypto.randomUUID(),
    ){
        if(!roomId){
            throw new Error("roomId required")
        }

        if(!payload ||
            typeof payload != "object"
        ){
            throw new Error("payload required")
        }

        this.rtm.send(
            EVENTS.CHAT_MESSAGE,
            {
                room_id: roomId,
                message: JSON.stringify(payload),
                message_id: messageId
            }
        );

        return messageId;
    }

    typingStart(roomId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        this.rtm.send(
            EVENTS.TYPING_START,
            {
                room_id: roomId
            }
        );
    }

    typingStop(roomId) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        this.rtm.send(
            EVENTS.TYPING_STOP,
            {
                room_id: roomId
            }
        );
    }

    deleteMessage(
        roomId,
        messageId
    ) {

        if (!roomId) {
            throw new Error("roomId required");
        }

        if (!messageId) {
            throw new Error("messageId required");
        }

        this.rtm.send(
            EVENTS.CHAT_DELETE,
            {
                room_id: roomId,
                message_id: messageId
            }
        );
    }
}